for i := 0; i < len(a); i++ {
	for j := i + 1; j < len(a); j++ {
		if a[i] == a[j] {
			return true
		}
	}
}

// O(n) по времени, O(n) по памяти
seen := make(map[int]struct{}, len(a))
for _, x := range a {
	if _, ok := seen[x]; ok {
		return true
	}
	seen[x] = struct{}{}
}

